//@ts-check
/** Browser bootstrap: real environment in, one running app document out. */

import { exportProject } from '@jarenjs/studio/export';
import './styles.css';
import '@jarenjs/md/styles/md.css';
import '@jarenjs/mermaid/styles/mermaid.css';
import '@jarenjs/calc/styles/calc.css';
import '@jarenjs/charts/styles/charts.css';
import '@jarenjs/collection/styles/collection.css';
import '@jarenjs/studio/styles/studio.css';
import '@jarenjs/studio/styles/flow.css';
import '@jarenjs/studio/styles/data.css';
import '@jarenjs/play/styles/play.css';
import { bindCalcKeyboard } from '@jarenjs/calc/component';
import { createSiteApp } from './app/createSiteApp.js';
import { md } from './boundaries/markdown.js';
import { parseHash } from './lib/route.js';
import { createHashRouteSubscription } from '@jarenjs/app/routes';
import { createMotion, prefersReducedMotion } from './lib/motion.js';
import { readTheme, writeTheme } from './lib/theme.js';
import { readLang, writeLang, searchLanguage } from './lib/lang.js';
import { isSiteLanguage, languageDir, warmSitePacks } from './boundaries/lang.js';

const BASE = import.meta.env.BASE_URL;
/** The build-generated site data, by the name the app asks for it under. */
const SITE_FILES = {
  packages: 'site/packages.json', content: 'site/content.json',
  cards: 'site/cards.json', build: 'build.json', corpus: 'site/spatial-corpus.json',
};
const IDE_KEY = 'jaren-ide';
// Keep the existing 8000-character share tokens plus deployment URL overhead.
const routes = createHashRouteSubscription({ window, maxLength: 65536, maxQueryEntries: 1024 });

/** A localStorage-backed JSON slot; failures degrade to in-memory. */
const jsonStore = (key) => ({
  key, reliable: true,
  read: () => {
    try {
      const raw = localStorage.getItem(key);
      return raw === null ? null : JSON.parse(raw);
    }
    catch {
      return null;
    }
  },
  write: (data) => {
    try {
      localStorage.setItem(key, JSON.stringify(data));
    }
    catch {
      // storage full or unavailable: the session keeps working
    }
  },
});

const theme = readTheme(() => localStorage, () => matchMedia('(prefers-color-scheme: dark)').matches);
document.documentElement.classList.toggle('dark', theme === 'dark');

// the site language: a `?lang=` link wins over the stored choice (the
// route applies the hash form; the search form is read here), the stored
// choice over English. A search-part link applies once: it is remembered
// and leaves the address bar before the app boots, the hash kept.
const linked = searchLanguage(location.search);
if (linked.lang !== null) {
  if (isSiteLanguage(linked.lang)) writeLang(() => localStorage, linked.lang);
  history.replaceState(history.state, '', `${location.pathname}${linked.search}${location.hash}`);
}
const storedLang = isSiteLanguage(linked.lang) ? linked.lang : readLang(() => localStorage);
const lang = isSiteLanguage(storedLang) ? storedLang : null;
/** Put a language on the document, so a screen reader and the layout follow it. @param {string} code @param {'ltr' | 'rtl'} dir */
const putLang = (code, dir) => {
  document.documentElement.lang = code;
  document.documentElement.dir = dir;
};
if (lang !== null) putLang(lang, languageDir(lang));

// Diagrams render complete; hydration only ADDS pan/zoom to them, so it runs
// after the DOM settles rather than as part of any frame. `md.hydrate` is
// idempotent — it skips an element whose content hash it has already wired —
// so re-running it on every mutation is cheap and needs no bookkeeping here.
const appNode = document.getElementById('app');
const hydrateDiagrams = () => md.hydrate(appNode);
new MutationObserver(hydrateDiagrams).observe(appNode, { childList: true, subtree: true });

const app = createSiteApp({
  node: appNode,
  document,
  initialTheme: theme,
  initialLang: lang,
  // a link param that applies once (`?lang=`) leaves the address bar
  replaceHash: (hash) => history.replaceState(history.state, '', `${location.pathname}${location.search}${hash}`),
  applyLang: (code, dir) => {
    putLang(code, dir);
    writeLang(() => localStorage, code);
  },
  fetchJson: (name) =>
    fetch(`${BASE}benchmarks/${encodeURIComponent(name)}.json`).then((response) => (
      response.ok ? response.json() : Promise.reject(new Error(String(response.status)))
    )),
  // what the build generated about the repository itself. The names are
  // the site's, not the deployment's — a path lives here, beside the
  // benchmark route above, and never in the state document
  fetchSite: (name) => {
    const file = SITE_FILES[name];
    if (file === undefined) return Promise.reject(new Error(`unknown site artifact '${name}'`));
    return fetch(`${BASE}${file}`).then((response) => (
      response.ok ? response.json() : Promise.reject(new Error(String(response.status)))
    ));
  },
  fetchText: (url) =>
    fetch(url).then((response) => (
      response.ok
        ? response.text()
        : Promise.reject(new Error(`${response.status} ${response.statusText}`))
    )),
  lockScroll: (on) => {
    document.body.classList.toggle('dialog-open', on);
  },
  revealActiveTab: () => {
    for (const el of document.querySelectorAll('.tabs .tab.active, .docs-sections .docs-link.active')) {
      el.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    }
  },
  // the site's motion layer, installed over each committed frame
  syncMotion: createMotion(document),
  // an in-page link in a rendered document: the target heading carries
  // the id @jarenjs/md minted for it. The header overlap is the
  // stylesheet's job (`--md-scroll-margin`), so this stays one line —
  // and the glide is motion like any other, so a reader who asked for
  // none is taken straight there.
  scrollToAnchor: (id) => {
    document.getElementById(id)?.scrollIntoView({
      block: 'start',
      behavior: prefersReducedMotion(window) ? 'auto' : 'smooth',
    });
  },
  applyTheme: (next) => {
    document.documentElement.classList.toggle('dark', next === 'dark');
    writeTheme(() => localStorage, next);
  },
  listenHash: (cb) => routes({ action: 'route' }, (_action, route) => cb(parseHash(route.raw))),
  navigate: routes.navigate,
  share: (hash) => {
    const url = `${location.origin}${location.pathname}${hash}`;
    navigator.clipboard?.writeText(url).catch(() => {});
    return url;
  },
  storage: jsonStore(IDE_KEY),
  // the Studio's "keep it" escape hatch: save the document as a file
  download: (filename, text) => {
    const url = URL.createObjectURL(new Blob([text], { type: 'application/json' }));
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = filename;
    anchor.click();
    URL.revokeObjectURL(url);
    return true;
  },
  exportProject: async (project) => {
    const base = `${BASE}studio-offline/`;
    const response = await fetch(base + 'manifest.json');
    if (!response.ok) throw new Error('Offline runtime assets are unavailable.');
    const manifest = await response.json();
    const entries = await Promise.all(manifest.files.map(async (name) => {
      if (!/^[A-Za-z0-9_.-]+$/.test(name)) throw new Error('Invalid runtime asset name');
      const asset = await fetch(base + name);
      if (!asset.ok) throw new Error(`Cannot load offline asset ${name}`);
      return [name, new Uint8Array(await asset.arrayBuffer())];
    }));
    const zip = exportProject(project, Object.fromEntries(entries));
    const url = URL.createObjectURL(new Blob([zip], { type: 'application/zip' }));
    const anchor = document.createElement('a');
    anchor.href = url; anchor.download = 'jaren-project.zip'; anchor.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    return true;
  },
  // `download`'s twin: open the file picker and hand back what was chosen.
  // Resolves null when the user dismisses it — there is no cancel event, so
  // the input is discarded either way and a dismissed picker simply never
  // resolves a file. A host without this capability omits it and the
  // surface says so, exactly as it does for a missing `download`.
  openFile: (accept = '.json,application/json') => new Promise((resolve) => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = accept;
    input.addEventListener('change', () => {
      const file = input.files?.[0];
      if (file === undefined) { resolve(null); return; }
      file.text().then((text) => resolve({ name: file.name, text }), () => resolve(null));
    }, { once: true });
    input.click();
  }),

});

// Re-discover late browser support after focus; ownership stays with the app.
const refreshWebMcp = () => { if (app.webmcp.status === 'unavailable') void app.webmcp.refresh(); };
addEventListener('focus', refreshWebMcp);
const releasePage = event => {
  if (event.persisted) return;
  removeEventListener('pagehide', releasePage);
  removeEventListener('focus', refreshWebMcp);
  app.destroy();
};
addEventListener('pagehide', releasePage);

// ——— the mobile keyboard seam (browser-only; headless hosts never load
// this bootstrap, so they no-op by construction) ———
// When the on-screen keyboard opens, the LAYOUT viewport keeps its height
// but the VISUAL viewport shrinks — a focused editor near the bottom ends
// up behind the keys. Publish the difference as a CSS var (`--kb-inset`);
// the active editor pane reserves it as bottom padding, so the caret
// always has scroll room above the keyboard line.
const publishKeyboardInset = () => {
  const vv = window.visualViewport;
  if (!vv) return;
  const inset = Math.max(0, document.documentElement.clientHeight - vv.height);
  document.documentElement.style.setProperty('--kb-inset', `${inset}px`);
};
if (window.visualViewport) {
  window.visualViewport.addEventListener('resize', publishKeyboardInset);
  window.visualViewport.addEventListener('scroll', publishKeyboardInset);
  publishKeyboardInset();
}
// While an editor is focused: mark the body (the sticky header un-sticks
// so it cannot cover the field) and center the field in the visual
// viewport, clear of both the header and the keyboard.
// the site's editors carry `.editor`; the @jarenjs/studio component's
// carries its own `.js-editor-input` — both get the seam
const isSeamEditor = (target) => target?.classList !== undefined
  && (target.classList.contains('editor') || target.classList.contains('js-editor-input'));
document.addEventListener('focusin', (event) => {
  const target = /** @type {any} */ (event.target);
  if (!isSeamEditor(target)) return;
  document.body.classList.add('kb-editing');
  target.scrollIntoView({ block: 'center', behavior: 'instant' });
});
document.addEventListener('focusout', (event) => {
  const target = /** @type {any} */ (event.target);
  if (isSeamEditor(target)) document.body.classList.remove('kb-editing');
});

// the calculator's keypad takes typing while it holds focus (#/calculator)
bindCalcKeyboard(document, app);

// close the nav dropdown groups on Escape or a click outside the header nav
// (the in-nav triggers own opening; route/set closes them on navigation)
addEventListener('keydown', (event) => {
  if (event.key === 'Escape' && app.getState().navOpen) app.dispatch('nav/close');
});
document.addEventListener('click', (event) => {
  const target = /** @type {any} */ (event.target);
  if (app.getState().navOpen && !(target?.closest && target.closest('#site-nav'))) {
    app.dispatch('nav/close');
  }
});

// PWA: register the service worker in production builds
if (import.meta.env.PROD && 'serviceWorker' in navigator) {
  addEventListener('load', () => {
    navigator.serviceWorker.register(`${BASE}sw.js`, { scope: BASE }).catch(() => {});
    // the service worker caches what it serves: once it controls the page,
    // fetch the stored language's packs once, on idle, so they are there
    // offline (none for English; a language picked later is cached as it loads)
    const warm = () => (window.requestIdleCallback ?? setTimeout)(() => { warmSitePacks(lang).catch(() => {}); });
    if (navigator.serviceWorker.controller) warm();
    else navigator.serviceWorker.addEventListener('controllerchange', warm, { once: true });
  });
}
